import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3003';

interface Notification {
    NotificationID: number;
    Message: string;
    IsRead: boolean;
    CreatedAt: string;
}

const NotificationsView = () => {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [error, setError] = useState<string | null>(null);

    const fetchNotifications = async () => {
        try {
            const response = await axios.get(`${API_URL}/notifications/hospital`);
            setNotifications(response.data);
        } catch (err) {
            setError('Failed to fetch notifications.');
            console.error(err);
        }
    };

    useEffect(() => {
        fetchNotifications();
    }, []);

    const handleMarkAsRead = async (notificationId: number) => {
        try {
            await axios.put(`${API_URL}/notifications/${notificationId}`, { isRead: true });
            fetchNotifications();
        } catch (err) {
            setError('Failed to mark notification as read.');
            console.error(err);
        }
    };

    if (error) return <div className="alert error">{error}</div>;

    return (
        <div className="notifications-container">
            <h2>Notifications</h2>
            {notifications.length === 0 ? (
                <p>No new notifications.</p>
            ) : (
                <ul className="notifications-list">
                    {notifications.map((notification) => (
                        <li key={notification.NotificationID} className={notification.IsRead ? 'read' : 'unread'}>
                            <div className="notification-content">
                                <p>{notification.Message}</p>
                                <span className="notification-time">{new Date(notification.CreatedAt).toLocaleString()}</span>
                            </div>
                            {!notification.IsRead && (
                                <button onClick={() => handleMarkAsRead(notification.NotificationID)} className="button">
                                    Mark as Read
                                </button>
                            )}
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default NotificationsView;
